#!/usr/bin/env python3
"""Cross-check monitor tables against an independent KMP prefix-function build."""
import importlib.util, random, sys
spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)


def prefix_function(p):
    pi = [0] * len(p)
    for i in range(1, len(p)):
        j = pi[i - 1]
        while j > 0 and p[i] != p[j]:
            j = pi[j - 1]
        if p[i] == p[j]:
            j += 1
        pi[i] = j
    return pi


def kmp_step(p, pi, k, a, allow_m):
    """longest j<=m with p[:j] suffix of p[:k]+[a]; k may equal m only if allow_m."""
    mm = len(p)
    if k == mm:
        k = pi[mm - 1] if mm else 0
    while k > 0 and (k >= mm or p[k] != a):
        k = pi[k - 1]
    if k < mm and p[k] == a:
        return k + 1
    return 0


def build_ref(op, p, sigma):
    mm = len(p)
    pi = prefix_function(p) if mm else []
    if op in ('match', 'startswith'):
        width = mm + 2
        fail = mm + 1
        tab = [[0] * width for _ in range(sigma)]
        for a in range(sigma):
            for k in range(mm):
                tab[a][k] = k + 1 if p[k] == a else fail
            tab[a][mm] = fail if op == 'match' else mm
            tab[a][fail] = fail
        return tab, mm
    width = mm + 1
    tab = [[0] * width for _ in range(sigma)]
    for a in range(sigma):
        for k in range(width):
            if op == 'contains' and k == mm:
                tab[a][k] = mm
            elif k == mm:
                tab[a][k] = kmp_step(p, pi, k, a, True)
            else:
                tab[a][k] = kmp_step(p, pi, k, a, False)
    return tab, mm


rnd = random.Random(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
bad = 0
trials = 0
for _ in range(4000):
    sigma = rnd.randint(1, 5)
    mm = rnd.randint(0, 16)
    alphabet = list(range(sigma))
    if mm and rnd.random() < 0.5:
        p = [rnd.choice(alphabet[:1])] * mm           # all-same patterns
    elif mm and rnd.random() < 0.5:
        base = [rnd.choice(alphabet) for _ in range(rnd.randint(1, 3))]
        p = (base * (mm // len(base) + 1))[:mm]       # periodic patterns
    else:
        p = [rnd.choice(alphabet) for _ in range(mm)]
    for op in ('endswith', 'contains'):
        toks = ['x%d' % i for i in range(sigma)]
        index = {t: i for i, t in enumerate(toks)}
        stoks = [toks[c] for c in p]
        tables, true_states, widths = m.build_monitors([(op, tuple(stoks))], sigma, index)
        mine = tables[0]
        ref, ref_true = build_ref(op, p, sigma)
        trials += 1
        if mine != ref or true_states[0] != ref_true:
            bad += 1
            print('MISMATCH', op, p, sigma)
            for a in range(sigma):
                if mine[a] != ref[a]:
                    print('  sym', a, mine[a], ref[a])
            if bad > 5:
                sys.exit(1)
print('%d monitor comparisons, %d mismatches' % (trials, bad))
